mapper.select:
SELECT e.employee_id AS employeeId, e.employee_no AS employeeNo, e.employee_name AS employeeName, e.nearest_station AS nearestStation, e.employment_status AS employmentStatus, e.work_status AS workStatus, u.user_name AS salesUserName FROM employees e INNER JOIN users u ON u.user_id = e.sales_user_id WHERE e.deleted_at IS NULL
AND e.employment_status = #{employmentStatus}
AND e.work_status = #{workStatus}
AND e.sales_user_id = #{salesUserId}
ORDER BY e.employee_no ASC
